-- Zes lange duurritten met variatie in de workout-bibliotheek, in de bestaande
-- vorm 'duur'. De onderbouwing staat in docs/lange-ritten-variatie.md.
--
-- Een sprint is een blok van 5 minuten dat begint met een burst van 30 seconden
-- (burstSeconds, src/lib/training/workouts.ts) en de rest losdraait.
--
-- intensity blijft 'endurance', zoals bij "Duur met tempoblokken"; kleur en naam
-- in een schema volgen het kernwerk (plannedWorkoutIntensity).

insert into public.training_workout_templates
  (form, title, description, duration_minutes, intensity, target_type, structure_json, is_standard)
select
  v.form, v.title, v.description, v.duration_minutes, v.intensity, v.target_type, v.structure_json, true
from (values
  ('duur', 'Duur 150 tempo aan het eind', 'Duurrit met twee tempoblokken in het laatste uur.', 150, 'endurance', 'power', '[{"label":"Warming-up","durationMinutes":15,"target":"50-65%","notes":"Rustig oplopend.","intensity":"endurance"},{"label":"Duur","durationMinutes":75,"target":"60-70%","notes":"Rustig blijven; eet en drink op tijd.","intensity":"endurance"},{"label":"Tempo 1/2","durationMinutes":20,"target":"81-86%","notes":"Gelijkmatig, cadans 85-95.","intensity":"tempo"},{"label":"Duur","durationMinutes":5,"target":"58-68%","notes":"Terug naar duurtempo.","intensity":"endurance"},{"label":"Tempo 2/2","durationMinutes":20,"target":"81-86%","notes":"Zelfde vermogen als het eerste blok.","intensity":"tempo"},{"label":"Cooling-down","durationMinutes":15,"target":"45-55%","notes":"Uitdraaien.","intensity":"recovery"}]'::jsonb),
  ('duur', 'Duur 180 met sprints', 'Rustige duurrit met elk uur drie sprints van 30 seconden.', 180, 'endurance', 'power', '[{"label":"Warming-up","durationMinutes":15,"target":"50-65%","notes":"Rustig oplopend.","intensity":"endurance"},{"label":"Duur","durationMinutes":30,"target":"60-70%","notes":"Rustig blijven.","intensity":"endurance"},{"label":"Sprint serie 1 1/3","durationMinutes":5,"target":"50-58%","notes":"30 sec voluit, zittend. Daarna losdraaien.","intensity":"recovery","burstSeconds":30},{"label":"Sprint serie 1 2/3","durationMinutes":5,"target":"50-58%","notes":"30 sec voluit, zittend. Daarna losdraaien.","intensity":"recovery","burstSeconds":30},{"label":"Sprint serie 1 3/3","durationMinutes":5,"target":"50-58%","notes":"30 sec voluit, zittend. Daarna losdraaien.","intensity":"recovery","burstSeconds":30},{"label":"Duur","durationMinutes":40,"target":"60-70%","notes":"Rustig blijven; eet en drink op tijd.","intensity":"endurance"},{"label":"Sprint serie 2 1/3","durationMinutes":5,"target":"50-58%","notes":"30 sec voluit, zittend. Daarna losdraaien.","intensity":"recovery","burstSeconds":30},{"label":"Sprint serie 2 2/3","durationMinutes":5,"target":"50-58%","notes":"30 sec voluit, zittend. Daarna losdraaien.","intensity":"recovery","burstSeconds":30},{"label":"Sprint serie 2 3/3","durationMinutes":5,"target":"50-58%","notes":"30 sec voluit, zittend. Daarna losdraaien.","intensity":"recovery","burstSeconds":30},{"label":"Duur","durationMinutes":40,"target":"60-70%","notes":"Rustig blijven; eet en drink op tijd.","intensity":"endurance"},{"label":"Sprint serie 3 1/3","durationMinutes":5,"target":"50-58%","notes":"30 sec voluit, zittend. Daarna losdraaien.","intensity":"recovery","burstSeconds":30},{"label":"Sprint serie 3 2/3","durationMinutes":5,"target":"50-58%","notes":"30 sec voluit, zittend. Daarna losdraaien.","intensity":"recovery","burstSeconds":30},{"label":"Sprint serie 3 3/3","durationMinutes":5,"target":"50-58%","notes":"30 sec voluit, zittend. Daarna losdraaien.","intensity":"recovery","burstSeconds":30},{"label":"Cooling-down","durationMinutes":10,"target":"45-55%","notes":"Uitdraaien.","intensity":"recovery"}]'::jsonb),
  ('duur', 'Duur 180 oplopend', 'Elk uur iets harder; het laatste stuk op intensieve duur.', 180, 'endurance', 'power', '[{"label":"Warming-up","durationMinutes":15,"target":"50-65%","notes":"Rustig oplopend.","intensity":"endurance"},{"label":"Rustige duur","durationMinutes":60,"target":"60-65%","notes":"Bewust rustig; eet en drink op tijd.","intensity":"endurance"},{"label":"Rustige duur","durationMinutes":50,"target":"66-70%","notes":"Iets hoger, nog steeds praattempo.","intensity":"endurance"},{"label":"Intensieve duur","durationMinutes":40,"target":"71-80%","notes":"Stevig doorrijden zonder te forceren.","intensity":"endurance"},{"label":"Cooling-down","durationMinutes":15,"target":"45-55%","notes":"Uitdraaien.","intensity":"recovery"}]'::jsonb),
  ('duur', 'Duur 180 fris en moe', 'Dezelfde drempelblokken aan het begin en na ruim twee uur.', 180, 'endurance', 'power', '[{"label":"Warming-up","durationMinutes":15,"target":"50-65%","notes":"Rustig oplopend.","intensity":"endurance"},{"label":"Drempel fris 1/2","durationMinutes":8,"target":"93-100%","notes":"Gelijkmatig; onthoud je vermogen.","intensity":"threshold"},{"label":"Herstel","durationMinutes":4,"target":"50-58%","notes":"Losdraaien.","intensity":"recovery"},{"label":"Drempel fris 2/2","durationMinutes":8,"target":"93-100%","notes":"Gelijkmatig; onthoud je vermogen.","intensity":"threshold"},{"label":"Duur","durationMinutes":110,"target":"60-70%","notes":"Rustig blijven; eet en drink op tijd.","intensity":"endurance"},{"label":"Drempel moe 1/2","durationMinutes":8,"target":"93-100%","notes":"Hetzelfde vermogen als aan het begin.","intensity":"threshold"},{"label":"Herstel","durationMinutes":4,"target":"50-58%","notes":"Losdraaien.","intensity":"recovery"},{"label":"Drempel moe 2/2","durationMinutes":8,"target":"93-100%","notes":"Hetzelfde vermogen als aan het begin.","intensity":"threshold"},{"label":"Cooling-down","durationMinutes":15,"target":"45-55%","notes":"Uitdraaien.","intensity":"recovery"}]'::jsonb),
  ('duur', 'Duur 210 drempel aan het eind', 'Lange rit met drie drempelblokken na tweeënhalf uur.', 210, 'endurance', 'power', '[{"label":"Warming-up","durationMinutes":15,"target":"50-65%","notes":"Rustig oplopend.","intensity":"endurance"},{"label":"Duur","durationMinutes":150,"target":"60-70%","notes":"Rustig blijven; eet en drink op tijd.","intensity":"endurance"},{"label":"Drempel 1/3","durationMinutes":8,"target":"93-100%","notes":"Gelijkmatig; niet te hard starten.","intensity":"threshold"},{"label":"Herstel 1/3","durationMinutes":4,"target":"50-58%","notes":"Losdraaien.","intensity":"recovery"},{"label":"Drempel 2/3","durationMinutes":8,"target":"93-100%","notes":"Gelijkmatig; niet te hard starten.","intensity":"threshold"},{"label":"Herstel 2/3","durationMinutes":4,"target":"50-58%","notes":"Losdraaien.","intensity":"recovery"},{"label":"Drempel 3/3","durationMinutes":8,"target":"93-100%","notes":"Gelijkmatig; niet te hard starten.","intensity":"threshold"},{"label":"Cooling-down","durationMinutes":13,"target":"45-55%","notes":"Uitdraaien.","intensity":"recovery"}]'::jsonb),
  ('duur', 'Duur 240', 'Vier uur rustige duur.', 240, 'endurance', 'power', '[{"label":"Warming-up","durationMinutes":15,"target":"50-65%","notes":"Rustig oplopend.","intensity":"endurance"},{"label":"Duur","durationMinutes":70,"target":"60-72%","notes":"Gelijkmatig, cadans 85-95.","intensity":"endurance"},{"label":"Duur","durationMinutes":70,"target":"60-72%","notes":"Eet en drink op tijd.","intensity":"endurance"},{"label":"Duur","durationMinutes":70,"target":"60-72%","notes":"Rustig blijven, ook op de klimmetjes.","intensity":"endurance"},{"label":"Cooling-down","durationMinutes":15,"target":"45-55%","notes":"Uitdraaien.","intensity":"recovery"}]'::jsonb)
) as v(form, title, description, duration_minutes, intensity, target_type, structure_json)
on conflict (form, title) where is_standard do update
set
  description = excluded.description,
  duration_minutes = excluded.duration_minutes,
  intensity = excluded.intensity,
  target_type = excluded.target_type,
  structure_json = excluded.structure_json,
  updated_at = now();

notify pgrst, 'reload schema';
